public class MembershipSettlement{static class GymMember{private static int count;private final String membershipNumber;private int feesPaid;GymMember(int f){membershipNumber="GYM-"+(++count+2000);}void payFee(int a){feesPaid+=a;}void payFee(int a,String m){payFee(a);}int getFeesPaid(){return feesPaid;}static int getMembersEnrolled(){return count;}}static class GroupClassMember extends GymMember{GroupClassMember(int f){super(f);}}static boolean isValidReferralCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='G'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3));}static String processWeeklyCheckIn(GymMember[] a){int p=0,n=0,g=0;for(GymMember m:a){if(m==null){n++;continue;}p++;if(m instanceof GroupClassMember)g++;}return p+" processed | "+n+" null skipped | "+g+" group | "+(p-g)+" individual";}}